export function getLocalizedSpokenItem(item, lang = 'en') {
  const norm = String(lang || 'en').toLowerCase().trim();
  const base = norm.split(/[-_]/)[0];
  const meaning =
    item.meanings?.[norm] ||
    item.meanings?.[base] ||
    item.meanings?.en ||
    item.formal ||
    '';
  const explanation =
    item.explanations?.[norm] ||
    item.explanations?.[base] ||
    item.explanations?.en ||
    '';
  const exampleTranslation =
    item.exampleTranslations?.[norm] ||
    item.exampleTranslations?.[base] ||
    item.exampleTranslations?.en ||
    '';
  return {
    ...item,
    meaning,
    explanation,
    exampleTranslation,
  };
}
